rule CobaltStrike_Beacon_Payload {
    meta:
        description = "Detects Cobalt Strike beacon shellcode patterns"
        author = "SOC Team"
        tlp = "amber"
        reference = "https://attack.mitre.org/software/S0154/"
    strings:
        $a = { 6A 40 68 00 30 00 00 6A 14 8D 91 }
        $b = { B8 01 00 00 00 95 6A 10 59 F7 F9 } 
        $c = /414D53[0-9A-F]{4}00004D530000/ 
    condition:
        all of them
}

